SELECT jsonb_build_object('migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name)) FROM supabase_migrations.schema_migrations WHERE name LIKE '%home_workflow%' OR name LIKE '%geo_public%'),'home_helper_exists',to_regprocedure('zoi.public_home_actions(uuid)') IS NOT NULL,'seo_has_actions',position('public_home_actions' in pg_get_functiondef('public.seo_entity(text)'::regprocedure))>0) AS release_reconciliation;
